from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class OperationHistory(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    name = SchemaField(name='name', not_null=True)
    targets = SchemaField(name='targets')
    start_time = SchemaField(name='startTime', not_null=True)
    end_time = SchemaField(name='endTime')
    triggering_source = SchemaField(name='triggeringSource')
    user_name = SchemaField(name='userName', not_null=True)
    session_id = SchemaField(name='sessionId', not_null=True)
    triggering_ip_address = SchemaField(name='triggeringIpAddress', not_null=True)
    status = SchemaField(name='status', not_null=True)
    user_role = SchemaField(name='userRole')

    def __init__(self, id, name, targets, start_time, end_time, triggering_source, user_name, session_id,
                 triggering_ip_address, status, user_role):
        self.id = id
        self.name = name
        self.targets = targets
        self.start_time = start_time
        self.end_time = end_time
        self.triggering_source = triggering_source
        self.user_name = user_name
        self.session_id = session_id
        self.triggering_ip_address = triggering_ip_address
        self.status = status
        self.user_role = user_role

        super(OperationHistory, self).__init__()


class GetOperationHistoryResponse(SchemaObject):
    revision = SchemaField(name='revision', not_null=True)
    created = SchemaField(name='created', not_null=True, klass=OperationHistory, many=True)
    updated = SchemaField(name='updated', not_null=True, klass=OperationHistory, many=True)
    removed = SchemaField(name='removed', not_null=True)

    def __init__(self, revision, created, updated, removed):
        self.revision = revision
        self.created = created
        self.updated = updated
        self.removed = removed

        super(GetOperationHistoryResponse, self).__init__()

